import {RACE_LENGTH,raceLength} from './physics.js';
import {missionRows} from './missions.js';
export const RIVAL_NAMES=['Kestrel','Viper','Nova','Echo','Blaze'];
export function raceResults(state,{car,world,route='coast',raceReward,missionReward,profile}){
 const length=raceLength(state),playerTime=Number.isFinite(state.finishTime)?state.finishTime:state.time;
 const rivals=state.traffic.map((t,i)=>({id:String(t.id??i),name:RIVAL_NAMES[i]||'Rival '+(i+1),player:false,time:Number.isFinite(t.finishTime)?t.finishTime:null,distance:t.distance}));
 const entries=[...rivals,{id:'player',name:'You',player:true,time:playerTime,distance:length}].sort((a,b)=>a.time!==null&&b.time!==null?a.time-b.time||(a.player?1:b.player?-1:0):a.time!==null?-1:b.time!==null?1:b.distance-a.distance);
 return {version:1,raceLength:length,car,world,route,difficulty:state.raceDifficulty||'medium',place:state.place,time:playerTime,standings:entries.map((e,i)=>({...e,position:i+1,behind:e.time===null?Math.max(0,Math.round(length-e.distance)):null,gap:e.time===null?null:e.time-playerTime})),raceReward,missionReward,total:raceReward+missionReward,wallet:profile.wallet+raceReward+missionReward,stats:{hits:state.impactCount||0,boosts:state.stripHits||0,ramps:state.rampHits||0,draft:Math.round((state.draftSeconds||0)*10)/10,nitro:state.nitroUses||0},missions:missionRows(profile).map(m=>({id:m.id,name:m.name,current:m.current,target:m.target,unit:m.unit||'',reward:m.reward,paid:m.paid}))};
}
export const resultTime=seconds=>{const ticks=Math.round(Math.max(0,seconds)*100),minutes=Math.floor(ticks/6000);return minutes+':'+String(Math.floor(ticks/100)%60).padStart(2,'0')+'.'+String(ticks%100).padStart(2,'0');};
const el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e;};
export function renderRaceResults(body,result,{carName,worldName,routeName=()=>'Coastline'}){
 body.replaceChildren();const hero=el('div','results-hero'),position=el('div','finish-place');position.append(el('strong','',String(result.place)),el('span','','/ 6'));const heading=el('div','finish-heading');heading.append(el('span','results-eyebrow','RACE COMPLETE'),el('h2','',result.place===1?'Victory':result.place<=3?'Podium finish':'Finish line'),el('p','',((result.raceLength||3000)/1000)+' km · '+carName(result.car)+' · '+routeName(result.route)+' · '+worldName(result.world)+' · '+result.difficulty));hero.append(position,heading,el('strong','finish-time',resultTime(result.time)));body.append(hero);
 const grid=el('div','results-grid'),left=el('section','results-standings'),right=el('section','results-rewards');left.append(el('h3','','Standings'),el('p','results-note',result.championship?'Official round times · All six finishers':'At your finish · Unfinished rivals: metres left'));const table=el('table','standings-table'),head=table.createTHead().insertRow();for(const name of ['POS','DRIVER','TIME / GAP']){const th=document.createElement('th');th.textContent=name;head.append(th);}const tbody=table.createTBody();for(const row of result.standings){const tr=tbody.insertRow();tr.className=row.player?'is-player':'';tr.insertCell().textContent=String(row.position).padStart(2,'0');tr.insertCell().textContent=row.name;tr.insertCell().textContent=row.player?resultTime(row.time):row.time===null?row.behind+' m left':(row.gap>0?'+':'−')+Math.abs(row.gap).toFixed(2)+' s';}left.append(table);
 right.append(el('h3','','Rewards'));const breakdown=el('dl','reward-breakdown');for(const [label,value] of [['Finish',result.raceReward],['Missions',result.missionReward],...(result.championshipBonus? [['Championship',result.championshipBonus]]:[])])breakdown.append(el('dt','',label),el('dd','','+'+value+' ◉'));breakdown.append(el('dt','reward-total','Total'),el('dd','reward-total','+'+result.total+' ◉'));right.append(breakdown,el('p','results-wallet','Wallet after race · ◉ '+result.wallet),el('h3','results-mission-heading','Missions'));
 for(const m of result.missions){const row=el('div','result-mission');row.append(el('span','',m.name),el('b','',m.paid?'✓ Paid':(m.unit==='s'?m.current.toFixed(1):m.current)+' / '+m.target+(m.unit?' '+m.unit:'')));right.append(row);}grid.append(left,right);body.append(grid);
 const stats=el('div','results-stats');for(const [label,value] of [['Boosts',result.stats.boosts],['Ramps',result.stats.ramps],['Draft',result.stats.draft+' s'],['N₂O',result.stats.nitro],['Car hits',result.stats.hits]]){const item=el('div');item.append(el('strong','',value),el('small','',label));stats.append(item);}body.append(stats);
}
